proc myFind[T](arr: openArray[T], pred: proc(x: T): bool): Option[T] =
  for x in arr:
    if pred(x):
      return some(x)
  return none(T)

when isMainModule:
  let nums = @[1, 3, 5, 8, 9]
  let evenOpt = myFind(nums, proc(x: int): bool = x mod 2 == 0)
  if evenOpt.isSome:
    echo "Found even: ", evenOpt.get()
  else:
    echo "No even found"

proc myZip[T, U](a: openArray[T], b: openArray[U]): seq[(T, U)] =
  let minLen = min(a.len, b.len)
  result = newSeq[(T, U)](minLen)
  for i in 0 ..< minLen:
    result[i] = (a[i], b[i])

when isMainModule:
  let names = ["Alice", "Bob", "Charlie"]
  let ages = [25, 30]
  let zipped = myZip(names, ages)
  echo zipped

proc myPartition[T](arr: openArray[T], pred: proc(x: T): bool): tuple[pass: seq[T], fail: seq[T]] =
  result.pass = newSeq[T]()
  result.fail = newSeq[T]()
  for x in arr:
    if pred(x):
      result.pass.add(x)
    else:
      result.fail.add(x)

when isMainModule:
  let nums = [1, 2, 3, 4, 5, 6]
  let (evens, odds) = myPartition(nums, proc(x: int): bool = x mod 2 == 0)
  echo "Evens: ", evens
  echo "Odds: ", odds

import std/tables

proc myGroupBy[T, K](arr: openArray[T], keyFunc: proc(x: T): K): Table[K, seq[T]] =
  result = initTable[K, seq[T]]()
  for x in arr:
    let k = keyFunc(x)
    if k notin result:
      result[k] = @[x]
    else:
      result[k].add(x)

