proc myChunk[T](arr: openArray[T], size: Positive): seq[seq[T]] =
  result = newSeq[seq[T]]()
  var current = newSeq[T]()
  for i, x in arr:
    current.add(x)
    if current.len == size or i == arr.high:
      result.add(current)
      current = newSeq[T]()

