type
  Result[T, E] = object
    case isOk: bool
    of true: val: T
    of false: err: E

proc getSuccess[T, E](opt: Option[Result[T, E]]): Option[T] =
  if opt.isSome:
    let res = opt.get()
    if res.isOk:
      return some(res.val)
  return none(T)

