  let o = some(r)
  let unwrapped = getSuccess(o)
  if unwrapped.isSome:
    echo unwrapped.get()

type
  FilterConstraint[T] = concept f
    f.keep(default(T)) is bool

type
  EvenFilter = object

proc keep(f: EvenFilter, val: int): bool =
  val mod 2 == 0

proc filterData[F: FilterConstraint[int]](f: F, data: openArray[int]): seq[int] =
  for x in data:
    if f.keep(x): result.add(x)

when isMainModule:
  let ef = EvenFilter()
  echo filterData(ef, [1, 2, 3, 4, 5])

